// Builds docs/sample_report.pdf and docs/sample_data.csv from testdata/log.json
const C = require('../web/core.js'), fs = require('fs');
const L = JSON.parse(fs.readFileSync(__dirname + '/log.json'));
const R = C.computeReport(L);
const pt = {name:'Simulated adult (test data)', id:'SIM-001', sex:'', place:'front (sternum)', post:'lying on back', notes:'Generated by the PC physiological simulator: 18 s breath-hold, movement and a 40 degree posture change are included.'};
const d = new Date('2026-09-26T09:30:00');
fs.writeFileSync(__dirname + '/../docs/sample_report.pdf', Buffer.from(C.buildPdf(L, R, pt, d)));
fs.writeFileSync(__dirname + '/../docs/sample_data.csv', C.buildCsv(L, R, pt, d));
console.log('sample written');
